rep(28, 'физическому лицу; «административный арест; административное выдворение за пределы Российской Федерации иностранного гражданина» или лица без гражданства; дисквалификация',
    'физическому лицу; административный арест; «административное выдворение за пределы Российской Федерации иностранного гражданина или лица без гражданства»; дисквалификация')
for _q in (97, 98): rep(_q, '«передачи — общим весом не более 30 кг в месяц»', '«передачи общим весом не более 30 кг в месяц»')
rep(104, '— образование «Службы по вопросам гражданства и регистрации иностранных граждан МВД России».', '— образование Службы по вопросам гражданства и регистрации иностранных граждан МВД России.')
rep(105, 'проводится должностным «лицом одного пола с досматриваемым, в присутствии двух понятых того же пола»', 'проводится должностным лицом «одного пола с досматриваемым в присутствии двух понятых того же пола»')
