rep(120, '(по ср. //п. 13 Пленума № 21//', '(ср. //п. 13 Пленума № 21//')
rep(121, '(«в случае непосредственного обнаружения либо обращения граждан или организаций»)', '(в случае непосредственного обнаружения либо обращения граждан или организаций)')
