rep(34, '— в соответствии с международными договорами Российской Федерации (//ч. 5//).', '— по международным договорам Российской Федерации (//ч. 5//).')
rep(34, 'правонарушениях лиц, являющихся организаторами публичного мероприятия', 'правонарушениях организаторов публичного мероприятия')
rep(78, 'запрещено (//ч. 2 ст. 16//).', 'запрещено (//ч. 2 ст. 16 Закона № 44-ФЗ//).')
rep(78, 'органов местного самоуправления соответствующего муниципального образования и территориального органа МВД России (//ч. 1 ст. 12//)', 'органов местного самоуправления муниципального образования и территориального органа МВД России (//ч. 1 ст. 12//)')
rep(78, '- дружине выдаётся свидетельство — в течение 14 дней после внесения в реестр', '- свидетельство дружине выдают в течение 14 дней после внесения в реестр')
rep(78, '- полученные документы в течение трёх рабочих дней направляются', '- документы в течение трёх рабочих дней направляются')

# ── правки по сверке ссылок на части и пункты статей (раздел журнала «Повторная сверка ссылок на части и пункты»)
def repall(q, a, b):
    t = rd(q)
    if a not in t: return
    wr(q, t.replace(a, b)); print('q%03d ~ %s (%d)' % (q, a[:60], t.count(a)))
# контролёр-распорядитель определён в п. 3.4 ст. 2 Закона № 329-ФЗ (пункта 34 в статье нет)
rep(142, '(//п. 34 ст. 2 Закона о спорте//)', '(//п. 3.4 ст. 2 Закона о спорте//)')
